"use client";
import { useEffect, useRef, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Breadcrumb from "@/components/header/breadcrumb";
import { ApiError } from "@/lib/apiClient";
import priceFormat from "@/helpers/priceFormat";
import { formatPlainDate, addPlainDays } from "@/helpers/plainDate";
import {
  getPaymentDetail,
  getPaymentRequestDetail,
} from "@/services/booking/paymentDetail";
import Processing from "../result/processing";

/*
 * Durum yoklaması.
 *
 * Sağlıklı bir provizyon 5-20 saniye sürüyor; apiv3 bankaya 60 saniye veriyor
 * (config/payment.php `http.timeout`). O sınırı geçince metin "biraz daha sürüyor"a döner
 * ve yoklama seyrelir ama DURMAZ. Üst sınırda yoklama biter, ödeme bitmez — tahsilatın
 * kaydedilmesi bu sayfaya bağlı değil, kuyruk işi müşteri ne yaparsa yapsın tamamlar.
 */
const POLL_INTERVAL_MS = 2000;
const POLL_SLOW_AFTER_MS = 60000;
const POLL_SLOW_INTERVAL_MS = 10000;
const POLL_GIVE_UP_MS = 300000;

export default function Page({ referenceId }: { referenceId: string }) {
  const router = useRouter();
  const searchParams = useSearchParams();

  const token = searchParams.get("token") ?? "";
  const requestId = searchParams.get("request_id") ?? "";
  const requestToken = searchParams.get("request_token") ?? "";

  const [slow, setSlow] = useState(false);
  const [trip, setTrip] = useState<{
    subject?: string;
    image?: string;
    startsAt?: string;
    endsAt?: string;
  }>({});
  const [payment, setPayment] = useState<{ amount?: string; reference?: string }>({});

  // Sonuç sayfası: ödeme ekranının kendisi. Oraya dönüldüğünde tutarlar YENİDEN çekilir,
  // böylece "ödendi" bilgisi ile ekrandaki bakiye tutarlı olur.
  const resultUrl =
    `/booking/${referenceId}/payment?token=${encodeURIComponent(token)}` +
    `&request_id=${encodeURIComponent(requestId)}` +
    `&request_token=${encodeURIComponent(requestToken)}`;

  // Yönlendirme bir kez yapılır; yoklama turu ile çakışıp iki kez tetiklenmesin.
  const leaving = useRef(false);

  const leave = () => {
    if (leaving.current) return;
    leaving.current = true;
    router.replace(resultUrl);
  };

  // Turun görseli/tarihi yalnızca bu ekranı bilgilendirici kılmak için; gelmezse ekran
  // yine çalışır (bloklamaz).
  useEffect(() => {
    if (!token) return;

    getPaymentDetail(referenceId, token)
      .then((res) => {
        const days = res?.data?.tour?.duration_days ?? 0;
        const start = res?.data?.start_date ?? "";

        setTrip({
          subject: res?.data?.subject ?? res?.data?.tour?.name ?? "",
          image: res?.data?.tour?.image ?? "",
          startsAt: start ? formatPlainDate(start) : "",
          endsAt: start && days > 1 ? formatPlainDate(addPlainDays(start, days - 1)) : "",
        });
      })
      .catch(() => {});
  }, [referenceId, token]);

  useEffect(() => {
    // Yoklanacak bir talep yoksa burada beklemenin anlamı yok.
    if (!requestId || !requestToken) {
      leave();

      return;
    }

    const startedAt = Date.now();
    let timer: ReturnType<typeof setTimeout>;
    let stopped = false;

    const check = async () => {
      try {
        const res = await getPaymentRequestDetail(referenceId, requestId, requestToken);

        if (res?.data?.amount > 0) {
          setPayment({
            amount: priceFormat({
              amount: res.data.amount,
              currency: res.data.currency,
              maximumFractionDigits: 2,
            }),
            reference: res.data.reference_id,
          });
        }

        /*
         * Beklemeye devam edilecek mi? Kararı API veriyor (`in_progress`), biz durum adı
         * SAYMIYORUZ — sayarken hata yapılmıştı (bkz. BookingPaymentRequestResource).
         * Ödeme sayfası da aynı alana baktığı için aramızda döngü oluşamaz.
         *
         * Alan hiç gelmiyorsa apiv3 henüz güncellenmemiştir (deploy penceresi: tsbnext
         * önce çıkar). O sürümde ödeme zaten tek istekte bitiyor, yani beklenecek bir şey
         * yok — müşteriyi burada asılı bırakmamak için durumdan türetiriz.
         */
        const inProgress =
          res?.data?.in_progress ??
          ["processing", "charging"].includes(res?.data?.status);

        if (!inProgress) {
          leave();

          return;
        }
      } catch (e) {
        /*
         * Kalıcı hata (bağlantı yanlış/eskimiş, talep başkasına ait) → beklemenin anlamı
         * yok, ödeme ekranına dön. Yalnız geçici ağ hataları yoklamayı sürdürür; aksi
         * hâlde müşteri hiç sonuçlanmayacak bir ekranda dakikalarca beklerdi.
         */
        if (e instanceof ApiError && e.status >= 400 && e.status < 500) {
          leave();

          return;
        }
      }

      if (stopped) return;

      const elapsed = Date.now() - startedAt;

      if (elapsed >= POLL_GIVE_UP_MS) return;
      if (elapsed >= POLL_SLOW_AFTER_MS) setSlow(true);

      timer = setTimeout(
        check,
        elapsed >= POLL_SLOW_AFTER_MS ? POLL_SLOW_INTERVAL_MS : POLL_INTERVAL_MS,
      );
    };

    check();

    return () => {
      stopped = true;
      clearTimeout(timer);
    };
  }, [referenceId, requestId, requestToken]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <main>
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6 tw-font-display">
        <Breadcrumb
          items={[
            { pageTitle: "Booking & Enquiry", pageUrl: "" },
            { pageTitle: "Payment", pageUrl: "" },
            { pageTitle: "Checking Payment", pageUrl: "" },
          ]}
        />
        <Processing
          subject={trip.subject}
          image={trip.image}
          startsAt={trip.startsAt}
          endsAt={trip.endsAt}
          referenceId={payment.reference}
          amount={payment.amount}
          slow={slow}
        />
      </div>
    </main>
  );
}
