import Image from "next/image";

/**
 * Banka cevabı beklenirken gösterilen TAM EKRAN.
 *
 * Neden ayrı bir ekran: "ödemeniz kontrol ediliyor" derken altında kart formunu açık
 * bırakmak çelişkili — müşteri hem bekletiliyor hem yeniden ödemeye davet ediliyordu.
 * Bu ekranda form yok, geri dönüş linki yok; tek yaptığı ne olduğunu anlatmak.
 *
 * Ekran müşteriye TEK bir şey söyler: ödeme kontrol ediliyor, sayfayı kapatma ve tekrar
 * ödeme deneme. Aşama aşama ne olduğunu anlatmak (3D doğrulandı, banka bekleniyor,
 * rezervasyon onaylanıyor) gereksiz ayrıntıydı; bu uyarı ise sayfanın dibinde değil,
 * müşterinin okuduğu tek cümlenin içinde olmalı — çifte tahsilatı önleyen cümle o.
 */
export default function Processing({
  subject,
  image,
  startsAt,
  endsAt,
  referenceId,
  amount,
  slow,
}: {
  subject?: string;
  image?: string;
  startsAt?: string;
  endsAt?: string;
  referenceId?: string;
  amount?: string;
  slow?: boolean;
}) {
  return (
    <div className="tw-mx-auto tw-flex tw-max-w-[560px] tw-flex-col tw-items-center tw-py-10 sm:tw-py-16">
      {/* Yükleniyor göstergesi: dışta yayılan halka, içte dönen yay. */}
      <div className="tw-relative tw-mb-7 tw-flex tw-h-[84px] tw-w-[84px] tw-items-center tw-justify-center">
        <span className="tw-absolute tw-inset-0 tw-animate-ping tw-rounded-full tw-bg-[#854ec9]/10" />
        <span className="tw-absolute tw-inset-[10px] tw-rounded-full tw-bg-[#f4eefc]" />
        <span className="tw-absolute tw-inset-0 tw-animate-spin tw-rounded-full tw-border-[3px] tw-border-solid tw-border-[#e6dcf5] tw-border-t-[#854ec9]" />
        <svg
          width="30"
          height="30"
          viewBox="0 0 16 16"
          fill="#854ec9"
          className="tw-relative"
          aria-hidden="true"
        >
          <path d="M8 1a2 2 0 0 1 2 2v4H6V3a2 2 0 0 1 2-2m3 6V3a3 3 0 0 0-6 0v4a2 2 0 0 0-2 2v5a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2" />
        </svg>
      </div>

      <h1
        className="tw-m-0 tw-text-center tw-font-display tw-text-[clamp(20px,2.4vw,26px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]"
        aria-live="polite"
      >
        Confirming your payment
      </h1>
      <p className="tw-m-0 tw-mt-2.5 tw-max-w-[420px] tw-text-center tw-text-[14.5px] tw-leading-relaxed tw-text-[#5d556c]">
        {slow
          ? "Your bank is taking longer than usual to answer. We are still checking this payment — please do not close this page or try paying again."
          : "We are checking this transaction with your bank. This usually takes a few seconds — please do not close this page or try paying again."}
      </p>

      {(subject || amount) && (
        <div className="tw-mt-8 tw-w-full tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_2px_14px_rgba(20,16,28,0.05)]">
          <div className="tw-flex tw-items-center tw-gap-3.5 tw-p-4">
            {image && (
              <div className="tw-relative tw-h-[58px] tw-w-[78px] tw-shrink-0 tw-overflow-hidden tw-rounded-xl">
                <Image src={image} alt={subject ?? ""} fill sizes="78px" className="tw-object-cover" />
              </div>
            )}
            <div className="tw-min-w-0">
              <p className="tw-m-0 tw-truncate tw-text-[14.5px] tw-font-bold tw-text-[#14101c]">
                {subject}
              </p>
              {(startsAt || endsAt) && (
                <p className="tw-m-0 tw-mt-1 tw-text-[12.5px] tw-text-[#6b6577]">
                  {startsAt}
                  {endsAt && startsAt !== endsAt ? ` — ${endsAt}` : ""}
                </p>
              )}
            </div>
          </div>

          <dl className="tw-m-0 tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-px-4 tw-py-3 tw-text-[13px]">
            {amount && (
              <div className="tw-flex tw-items-center tw-justify-between tw-gap-3">
                <dt className="tw-text-[#6b6577]">Amount</dt>
                <dd className="tw-m-0 tw-font-bold tw-text-[#14101c]">{amount}</dd>
              </div>
            )}
            {referenceId && (
              <div className="tw-mt-1.5 tw-flex tw-items-center tw-justify-between tw-gap-3">
                <dt className="tw-text-[#6b6577]">Reference</dt>
                <dd className="tw-m-0 tw-font-medium tw-text-[#5d556c]">{referenceId}</dd>
              </div>
            )}
          </dl>
        </div>
      )}
    </div>
  );
}
